import java.io.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ');

            int value = 0;
            while (c > ' ') {
                value = value * 10 + c - '0';
                c = read();
            }
            return value;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }
    }

    static class Tree {
        int n;
        int[] head, to, next;
        int edgeCount = 0;

        Tree(int n) {
            this.n = n;
            head = new int[n + 1];
            java.util.Arrays.fill(head, -1);
            to = new int[2 * (n - 1)];
            next = new int[2 * (n - 1)];
        }

        void addEdge(int a, int b) {
            to[edgeCount] = b;
            next[edgeCount] = head[a];
            head[a] = edgeCount++;
            to[edgeCount] = a;
            next[edgeCount] = head[b];
            head[b] = edgeCount++;
        }

        int farthest(int start, int[] parent) {
            int[] distance = new int[n + 1];
            java.util.Arrays.fill(parent, -1);
            int[] queue = new int[n];
            int front = 0, back = 0;
            queue[back++] = start;
            parent[start] = 0;

            int farthest = start;
            while (front < back) {
                int v = queue[front++];
                if (distance[v] > distance[farthest]) farthest = v;

                for (int e = head[v]; e != -1; e = next[e]) {
                    int u = to[e];
                    if (parent[u] == -1) {
                        parent[u] = v;
                        distance[u] = distance[v] + 1;
                        queue[back++] = u;
                    }
                }
            }
            return farthest;
        }

        int center() {
            int[] parent = new int[n + 1];
            int endpointA = farthest(1, parent);
            int endpointB = farthest(endpointA, parent);

            int[] path = new int[n];
            int length = 0;
            for (int v = endpointB; v != 0; v = parent[v]) {
                path[length++] = v;
                if (v == endpointA) break;
            }
            return path[length / 2];
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int n = fs.nextInt();
        int m = fs.nextInt();

        Tree circle = new Tree(n);
        for (int i = 0; i < n - 1; i++) {
            circle.addEdge(fs.nextInt(), fs.nextInt());
        }

        Tree square = new Tree(m);
        for (int i = 0; i < m - 1; i++) {
            square.addEdge(fs.nextInt(), fs.nextInt());
        }

        System.out.println(circle.center() + " " + square.center());
    }
}
